<template>
  <div class="w-full space-y-5 p-4 sm:p-6">
    <div class="breadcrumbs text-sm"><ul><li><NuxtLink :to="homePath">Home</NuxtLink></li><li><NuxtLink :to="auditPath">Audit</NuxtLink></li><li>Tender trail</li></ul></div>
    <div v-if="loading" class="flex justify-center py-20"><span class="loading loading-spinner loading-lg" /></div>
    <div v-else-if="errorMessage" class="alert alert-error"><Icon name="lucide:triangle-alert" class="h-5 w-5" />{{ errorMessage }}</div>
    <template v-else-if="record">
      <section class="card card-border bg-base-100 shadow-sm"><div class="card-body gap-5 p-5"><div class="flex flex-wrap items-start justify-between gap-4"><div><div class="flex flex-wrap items-center gap-2"><span class="font-mono text-xs text-base-content/50">{{ record.tender.tendernumber || 'Tender number pending' }}</span><span class="badge badge-sm badge-soft badge-info">{{ label(record.tender.status) }}</span></div><h1 class="mt-2 text-xl font-bold sm:text-2xl">{{ record.tender.title }}</h1><p class="mt-2 text-sm text-base-content/55">{{ record.tender.company?.name }} · APP {{ record.tender.plan?.year || record.tender.year }}</p></div><span class="badge badge-outline">{{ record.tender.procurement_method?.name || 'Method not set' }}</span></div>
        <div class="grid gap-3 border-t border-base-200 pt-4 sm:grid-cols-3"><div><p class="text-xs text-base-content/45">Created</p><p class="mt-1 text-sm font-medium">{{ dateTime(record.tender.created_at) }}</p></div><div><p class="text-xs text-base-content/45">Current stage</p><p class="mt-1 text-sm font-medium">{{ label(record.tender.status) }}</p></div><div><p class="text-xs text-base-content/45">Source APP lines</p><p class="mt-1 text-sm font-medium">{{ record.source_app_items?.length || 0 }}</p></div></div></div></section>
      <section class="card card-border bg-base-100 shadow-sm"><div class="card-body p-5"><h2 class="card-title text-lg">Source APP lines</h2><div class="mt-3 overflow-x-auto"><table class="table table-sm"><thead><tr><th>Reference</th><th>Description</th><th class="text-right">Planned</th><th class="text-right">Allocated to tender</th></tr></thead><tbody><tr v-for="item in record.source_app_items" :key="item.uuid"><td class="font-mono text-xs">{{ item.reference_no || '—' }}</td><td>{{ item.description }}</td><td class="text-right font-mono">{{ money(item.planned_total) }}</td><td class="text-right font-mono font-semibold">{{ money(item.allocated_total) }}</td></tr></tbody></table></div></div></section>
      <section class="card card-border bg-base-100 shadow-sm"><div class="card-body p-5"><div class="flex items-center justify-between gap-3"><h2 class="card-title text-lg">Lifecycle</h2><span class="badge badge-outline">{{ record.timeline?.length || 0 }} events</span></div><ul class="timeline timeline-vertical timeline-compact mt-6"><li v-for="event in record.timeline" :key="event.key"><div class="timeline-middle"><span :class="['grid h-8 w-8 place-items-center rounded-full', stageTone(event.stage)]"><Icon :name="stageIcon(event.stage)" class="h-4 w-4" /></span></div><div class="timeline-end timeline-box mb-5 w-full max-w-4xl border-base-200 bg-base-100"><div class="flex flex-wrap items-start justify-between gap-2"><div><span class="badge badge-sm badge-ghost">{{ event.stage }}</span><h3 class="mt-2 font-semibold">{{ event.title }}</h3></div><time class="text-xs text-base-content/50">{{ dateTime(event.occurred_at) }}</time></div><p class="mt-2 text-sm text-base-content/55">{{ event.actor?.name || 'System process' }}</p><p v-if="event.metadata?.comment" class="mt-2 rounded-lg bg-base-200/60 px-3 py-2 text-sm">{{ event.metadata.comment }}</p></div><hr /></li></ul></div></section>
    </template>
  </div>
</template>
<script setup>
const props = defineProps({ system: { type: Boolean, default: false } })
const route = useRoute(); const api = useAuditHelper(); const { can } = useCheckPermission()
const loading = ref(true); const errorMessage = ref(''); const record = ref(null)
const homePath = computed(() => props.system ? '/' : '/dashboard'); const auditPath = computed(() => props.system ? '/system-audits' : '/audits')
const label = value => String(value || '').replaceAll('_', ' ').toLowerCase().replace(/\b\w/g, letter => letter.toUpperCase())
const money = value => new Intl.NumberFormat('en-ZW', { style: 'currency', currency: 'USD' }).format(Number(value || 0))
const dateTime = value => value ? new Intl.DateTimeFormat('en-ZW', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value)) : '—'
const stageTone = stage => ({ Planning: 'bg-info text-info-content', 'Internal approval': 'bg-warning text-warning-content', Publication: 'bg-primary text-primary-content', 'Bid opening': 'bg-secondary text-secondary-content', Evaluation: 'bg-accent text-accent-content', Award: 'bg-success text-success-content', Exception: 'bg-error text-error-content' }[stage] || 'bg-neutral text-neutral-content')
const stageIcon = stage => ({ Planning: 'lucide:notebook-tabs', 'Internal approval': 'lucide:stamp', Publication: 'lucide:megaphone', 'Bid opening': 'lucide:folder-open', Evaluation: 'lucide:clipboard-check', Award: 'lucide:award', Exception: 'lucide:triangle-alert' }[stage] || 'lucide:history')
onMounted(async () => { const permission = props.system ? 'can.access.systemaudits' : 'can.access.peaudits'; if (!can(permission)) { errorMessage.value = 'You do not have permission to view this audit trail.'; loading.value = false; return } const { data, error } = await api.getTender(route.params.uuid); loading.value = false; if (error || data?.status === false) errorMessage.value = error?.data?.message || data?.message || 'Tender audit trail could not be loaded.'; else record.value = data.data })
</script>
